def _unique_paths(paths: Sequence[Path]) -> List[Path]:
    unique = {str(path.resolve()): path for path in paths}
    return sorted(unique.values(), key=lambda path: (path.name, str(path)))


def _crash_results_dir() -> Path:
    if Path(RESULTS_DIR) != DEFAULT_RESULTS_DIR and Path(CRASH_RESULTS_DIR) == DEFAULT_RESULTS_DIR / "crash_prediction":
        return Path(RESULTS_DIR) / "crash_prediction"
    return Path(CRASH_RESULTS_DIR)


def _clustering_results_dir() -> Path:
    if Path(RESULTS_DIR) != DEFAULT_RESULTS_DIR and Path(CLUSTERING_RESULTS_DIR) == DEFAULT_RESULTS_DIR / "clustering":
        return Path(RESULTS_DIR) / "clustering"
    return Path(CLUSTERING_RESULTS_DIR)


def _crash_result_dirs() -> List[Path]:
    dirs = [_crash_results_dir(), Path(RESULTS_DIR)]
    unique: List[Path] = []
    seen: set[str] = set()
    for path in dirs:
        key = str(path)
        if key not in seen:
            unique.append(path)
            seen.add(key)
    return unique


def _glob_crash_results(pattern: str) -> List[Path]:
    files: List[Path] = []
    for directory in _crash_result_dirs():
        if directory.exists():
            files.extend(directory.glob(pattern))
    unique = _unique_paths(files)
    crash_root = _crash_results_dir().resolve()
    return sorted(
        unique,
        key=lambda path: (
            path.name,
            0
            if str(path.resolve()).startswith(str(crash_root))
            else 1,
            str(path),
        ),
    )


def _crash_output_path(filename: str) -> Path:
    return _ensure_crash_results_dir() / filename


def _ensure_crash_results_dir() -> Path:
    output_dir = _crash_results_dir()
    output_dir.mkdir(parents=True, exist_ok=True)
    return output_dir


def _find_named_path(paths: Sequence[Path], name: str) -> Path:
    return next(path for path in paths if path.name == name)


def _cluster_result_dirs() -> List[Path]:
    dirs = [_clustering_results_dir(), Path(RESULTS_DIR)]
    unique: List[Path] = []
    seen: set[str] = set()
    for path in dirs:
        key = str(path)
        if key not in seen:
            unique.append(path)
            seen.add(key)
    return unique


def _glob_cluster_results(pattern: str) -> List[Path]:
    files: List[Path] = []
    for directory in _cluster_result_dirs():
        if directory.exists():
            files.extend(directory.glob(pattern))
    unique = _unique_paths(files)
    cluster_root = _clustering_results_dir().resolve()
    return sorted(
        unique,
        key=lambda path: (
            path.name,
            0
            if str(path.resolve()).startswith(str(cluster_root))
            else 1,
            str(path),
        ),
    )


class _StreamlitProgress:
    def __init__(self, total: int) -> None:
        self.total = max(1, int(total))
        self.value = 0
        self.text = st.empty()
        self.bar = st.progress(0)

    def set_description(self, label: str) -> None:
        self.text.text(label)

    def update(self, step: int = 1) -> None:
        self.value = min(self.total, self.value + int(step))
        percent = int((self.value / self.total) * 100)
        self.bar.progress(percent)

    def close(self) -> None:
        self.text.empty()


class _LiveTrainingCurvesBoard:
    def __init__(self, labels: Sequence[str]) -> None:
        self.labels = [str(label) for label in labels]
        self._meta_slots: Dict[str, object] = {}
        self._chart_slots: Dict[str, object] = {}
        if not self.labels:
            return

        container = st.container()
        with container:
            st.caption("Curvas en vivo")
            columns = st.columns(len(self.labels))
            for column, label in zip(columns, self.labels):
                with column:
                    st.markdown(f"**{label}**")
                    self._meta_slots[label] = st.empty()
                    self._chart_slots[label] = st.empty()
                    self._meta_slots[label].caption("Esperando entrenamiento")

    def update(
        self,
        label: str,
        curves_value: object,
        *,
        protocol_label: Optional[str] = None,
    ) -> None:
        if label not in self._chart_slots:
            return
        curves = _coerce_training_curves(curves_value)
        frame = _training_curves_frame(curves_value)
        if not curves or frame is None or frame.empty:
            return

        meta_parts: List[str] = []
        if protocol_label:
            meta_parts.append(str(protocol_label))
        meta_parts.append(
            f"epoch {int(curves.get('epochs_ran', 0))}/{int(curves.get('max_epochs', 0))}"
        )
        if bool(curves.get("early_stopping_triggered")):
            meta_parts.append("early stop")
        self._meta_slots[label].caption(" | ".join(meta_parts))

        alt = _import_altair()
        chart_slot = self._chart_slots[label]
        if alt is not None:
            chart = (
                alt.Chart(frame)
                .mark_line(point=True)
                .encode(
                    x=alt.X("epoch:Q", title="Epoch"),
                    y=alt.Y("loss:Q", title="Loss"),
                    color=alt.Color("serie:N", title="Curva"),
                )
                .properties(height=220)
            )
            chart_slot.altair_chart(chart, width="stretch")
        else:
            pivot_df = frame.pivot(index="epoch", columns="serie", values="loss")
            chart_slot.line_chart(pivot_df, height=220)


def _format_duration_compact(seconds: Optional[float]) -> str:
    if seconds is None or not np.isfinite(float(seconds)):
        return "-"
    total_seconds = max(0, int(round(float(seconds))))
    hours, remainder = divmod(total_seconds, 3600)
    minutes, secs = divmod(remainder, 60)
    if hours > 0:
        return f"{hours}h {minutes:02d}m {secs:02d}s"
    if minutes > 0:
        return f"{minutes}m {secs:02d}s"
    return f"{secs}s"


